SUPABASE_AUTH_JWT = os.environ.get("SUPABASE_AUTH_JWT", "")
AQL_DEVICE_TOKEN = os.environ.get("AQL_DEVICE_TOKEN", "")

KIT_ID = os.environ.get("AQL_KIT_ID", "")
